select

from t_voice_device a
where 1 = 1
 and a.voice_device_id = #{voiceDeviceId, jdbcType=VARCHAR}
 and a.voice_device_name like concat('%',#{voiceDeviceName, jdbcType=VARCHAR},'%')
 and a.std_device_id = #{stdDeviceId, jdbcType=BIGINT}
 and a.device_type = #{deviceType, jdbcType=VARCHAR}
 and a.config_id = #{configId, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.voice_type = #{voiceType, jdbcType=VARCHAR}
 and a.voice_model = #{voiceModel, jdbcType=VARCHAR}
 and a.voice_factory = #{voiceFactory, jdbcType=VARCHAR}

