mapper.select:
SELECT a.region_id AS Id, a.region_name AS label, a.up_region_id AS upId, b.region_name AS upName, "region" AS infoType, "" as dbValue, "" as fvalue FROM t_std_region a LEFT JOIN t_std_region b ON a.up_region_id = b.region_id UNION ALL ( SELECT a.voice_device_id AS id, a.voice_device_name AS label, a.up_region_id AS upId, b.region_name as upName, "device" AS infoType, concat(c.db_value, 'dB') as dbValue, concat(c.f_value, 'Hz')as fvalue FROM t_voice_device a left join t_voice_config c on a.config_id = c.config_id LEFT JOIN t_std_region b on a.up_region_id = b.region_id and a.voice_device_name like concat ('%',#{voiceDeviceName, jdbcType=VARCHAR},'%')
WHERE a.voice_device_id NOT IN ( SELECT monitor_device_id FROM sys_role_monitor_device srmd LEFT JOIN sys_user su ON srmd.role_id = su.role_id WHERE su.user_id = #{userId, jdbcType = BIGINT} )
)
